<?php require_once __DIR__.'/../includes/functions.php';$u=require_login();$id=(int)$u['id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=$_POST['act']??'';$gid=(int)($_POST['group_id']??0);if($act==='create'){$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');$subject=(int)($_POST['subject_id']??0);$level=$_POST['level']??'Beginner';$mode=$_POST['mode']??'Online';if(!$name||!$desc||!in_array($level,['Beginner','Intermediate','Advanced'])||!in_array($mode,['Online','Offline','Both'])){flash('danger','Complete the group details.');go('groups.php');}$pdo=db();$pdo->beginTransaction();$pdo->prepare('INSERT INTO study_groups(name,description,subject_id,level,study_mode,creator_id) VALUES(?,?,?,?,?,?)')->execute([$name,$desc,$subject?:null,$level,$mode,$id]);$new=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO group_members(group_id,user_id,role) VALUES(?,?,'admin')")->execute([$new,$id]);$pdo->commit();flash('success','Your study group is ready.');go('group-details.php?id='.$new);}if($act==='join')db()->prepare('INSERT IGNORE INTO group_members(group_id,user_id) SELECT id,? FROM study_groups WHERE id=? AND status=\'active\'')->execute([$id,$gid]);if($act==='leave')db()->prepare('DELETE FROM group_members WHERE group_id=? AND user_id=? AND role<>\'admin\'')->execute([$gid,$id]);flash('success',$act==='join'?'You joined the group.':'You left the group (group admins remain members).');go('groups.php');}$q=db()->prepare("SELECT g.*,s.name subject,(SELECT COUNT(*) FROM group_members m WHERE m.group_id=g.id) members,EXISTS(SELECT 1 FROM group_members m WHERE m.group_id=g.id AND m.user_id=?) joined FROM study_groups g LEFT JOIN subjects s ON s.id=g.subject_id WHERE g.status='active' ORDER BY g.created_at DESC");$q->execute([$id]);$groups=$q->fetchAll();$subjects=db()->query('SELECT id,name FROM subjects WHERE active=1 ORDER BY name')->fetchAll();page_start('Study groups'); ?><div class="row g-4"><div class="col-lg-8"><div class="row g-3"><?php foreach($groups as $g): ?><div class="col-md-6"><div class="card h-100"><div class="card-body"><div class="d-flex justify-content-between"><span class="tag"><?= e($g['level']) ?></span><span class="small text-secondary"><?= (int)$g['members'] ?> members</span></div><h2 class="h5 fw-bold mt-3"><?= e($g['name']) ?></h2><p class="text-secondary small"><?= e($g['description']) ?></p><div class="small mb-3"><?= e($g['subject']?:'Open topic') ?> · <?= e($g['study_mode']) ?></div><a class="btn btn-sm btn-outline-primary" href="group-details.php?id=<?= $g['id'] ?>">View group</a><?php if(!$g['joined']): ?><form method="post" class="d-inline"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="act" value="join"><input type="hidden" name="group_id" value="<?= $g['id'] ?>"><button class="btn btn-sm btn-primary">Join</button></form><?php elseif((int)$g['creator_id']!==$id): ?><form method="post" class="d-inline"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="act" value="leave"><input type="hidden" name="group_id" value="<?= $g['id'] ?>"><button class="btn btn-sm btn-outline-secondary">Leave</button></form><?php else: ?><span class="tag">Your group</span><?php endif ?></div></div><?php endforeach ?></div></div><div class="col-lg-4"><div class="card"><div class="card-body"><h2 class="h5 fw-bold">Create a group</h2><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="act" value="create"><label class="form-label">Group name</label><input class="form-control mb-3" name="name" required maxlength="140"><label class="form-label">Description</label><textarea class="form-control mb-3" name="description" required></textarea><label class="form-label">Subject</label><select class="form-select mb-3" name="subject_id"><option value="">Open topic</option><?php foreach($subjects as $s): ?><option value="<?= $s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach ?></select><div class="row"><div class="col-6"><label class="form-label">Level</label><select class="form-select mb-3" name="level"><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></div><div class="col-6"><label class="form-label">Mode</label><select class="form-select mb-3" name="mode"><option>Online</option><option>Offline</option><option>Both</option></select></div></div><button class="btn btn-primary w-100">Create group</button></form></div></div></div></div><?php page_end(); ?>
